CREATE SEQUENCE logs_ingest_sequence INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 1 NO CYCLE;;
CREATE TABLE analysis_state(project_id VARCHAR, state_key VARCHAR, value_json JSON NOT NULL, etag VARCHAR NOT NULL, updated_at_unix_nano UBIGINT NOT NULL, PRIMARY KEY(project_id, state_key));;
CREATE TABLE annotations(project_id VARCHAR, annotation_id VARCHAR, target_kind VARCHAR NOT NULL, trace_id VARCHAR, span_id VARCHAR, session_id VARCHAR, "text" VARCHAR NOT NULL, created_at_unix_nano UBIGINT NOT NULL, updated_at_unix_nano UBIGINT NOT NULL, etag VARCHAR NOT NULL, PRIMARY KEY(project_id, annotation_id));;
CREATE TABLE idempotency_keys(project_id VARCHAR, operation VARCHAR, idempotency_key VARCHAR, request_hash VARCHAR NOT NULL, resource_id VARCHAR NOT NULL, response_json JSON NOT NULL, created_at_unix_nano UBIGINT NOT NULL, PRIMARY KEY(project_id, operation, idempotency_key));;
CREATE TABLE logs(project_id VARCHAR, log_id VARCHAR, trace_id VARCHAR, span_id VARCHAR, event_name VARCHAR, session_id VARCHAR, time_unix_nano UBIGINT NOT NULL, observed_time_unix_nano UBIGINT, severity_number TINYINT NOT NULL, severity_text VARCHAR, body VARCHAR, service_name VARCHAR, attributes_json JSON, resource_json JSON, resource_entity_refs_json JSON, ingest_sequence BIGINT DEFAULT(nextval('logs_ingest_sequence')) NOT NULL, PRIMARY KEY(project_id, log_id));;
CREATE TABLE metric_exemplars(project_id VARCHAR, series_id VARCHAR, time_unix_nano UBIGINT, trace_id VARCHAR, PRIMARY KEY(project_id, series_id, time_unix_nano, trace_id));;
CREATE TABLE metric_points(project_id VARCHAR, series_id VARCHAR, time_unix_nano UBIGINT, start_time_unix_nano UBIGINT, "value" DOUBLE, histogram_count UBIGINT, histogram_sum DOUBLE, histogram_min DOUBLE, histogram_max DOUBLE, bucket_bounds_json JSON, bucket_counts_json JSON, PRIMARY KEY(project_id, series_id, time_unix_nano));;
CREATE TABLE metric_series(project_id VARCHAR, series_id VARCHAR, metric_name VARCHAR NOT NULL, metric_kind TINYINT NOT NULL, temporality TINYINT NOT NULL, is_monotonic TINYINT NOT NULL, unit VARCHAR, description VARCHAR, service_name VARCHAR, schema_url VARCHAR, attributes_json JSON, resource_json JSON, resource_entity_refs_json JSON, first_seen_unix_nano UBIGINT NOT NULL, last_seen_unix_nano UBIGINT NOT NULL, PRIMARY KEY(project_id, series_id));;
CREATE TABLE qyl_schema_meta(singleton UTINYINT PRIMARY KEY, authoritative_schema_hash VARCHAR NOT NULL, derived_schema_hash VARCHAR NOT NULL, updated_at TIMESTAMP WITH TIME ZONE DEFAULT(current_timestamp) NOT NULL);;
CREATE TABLE saved_queries(project_id VARCHAR, saved_query_id VARCHAR, "name" VARCHAR NOT NULL, description VARCHAR, signal VARCHAR NOT NULL, filter_json JSON NOT NULL, created_at_unix_nano UBIGINT NOT NULL, updated_at_unix_nano UBIGINT NOT NULL, etag VARCHAR NOT NULL, PRIMARY KEY(project_id, saved_query_id));;
CREATE TABLE spans(project_id VARCHAR, span_id VARCHAR, trace_id VARCHAR, parent_span_id VARCHAR, session_id VARCHAR, "name" VARCHAR NOT NULL, kind TINYINT NOT NULL, start_time_unix_nano UBIGINT NOT NULL, end_time_unix_nano UBIGINT NOT NULL, duration_ns UBIGINT NOT NULL, status_code TINYINT NOT NULL, service_name VARCHAR, gen_ai_provider_name VARCHAR, gen_ai_operation_name VARCHAR, gen_ai_output_type VARCHAR, gen_ai_request_model VARCHAR, gen_ai_response_model VARCHAR, gen_ai_input_tokens BIGINT, gen_ai_output_tokens BIGINT, gen_ai_cache_read_input_tokens BIGINT, gen_ai_cache_write_input_tokens BIGINT, gen_ai_reasoning_tokens BIGINT, attributes_json JSON, resource_json JSON, resource_entity_refs_json JSON, schema_url VARCHAR, status_message VARCHAR, events_json JSON, links_json JSON, scope_name VARCHAR, scope_version VARCHAR, PRIMARY KEY(project_id, trace_id, span_id));;
CREATE INDEX idx_annotations_project_id_created_at_unix_nano ON annotations(project_id, created_at_unix_nano);;
CREATE INDEX idx_annotations_project_id_session_id ON annotations(project_id, session_id);;
CREATE INDEX idx_annotations_project_id_trace_id ON annotations(project_id, trace_id);;
CREATE INDEX idx_annotations_updated_at_unix_nano ON annotations(updated_at_unix_nano);;
CREATE INDEX idx_idempotency_keys_created_at_unix_nano ON idempotency_keys(created_at_unix_nano);;
CREATE INDEX idx_logs_project_id_ingest_sequence ON logs(project_id, ingest_sequence);;
CREATE INDEX idx_logs_project_id_session_id ON logs(project_id, session_id);;
CREATE INDEX idx_logs_project_id_time_unix_nano ON logs(project_id, time_unix_nano);;
CREATE INDEX idx_logs_project_id_trace_id ON logs(project_id, trace_id);;
CREATE INDEX idx_logs_time_unix_nano ON logs(time_unix_nano);;
