CREATE INDEX idx_metric_points_project_id_time_unix_nano ON metric_points(project_id, time_unix_nano);;
CREATE INDEX idx_metric_series_project_id_metric_name ON metric_series(project_id, metric_name);;
CREATE INDEX idx_saved_queries_project_id_name ON saved_queries(project_id, "name");;
