CREATE INDEX idx_spans_project_id_gen_ai_operation_name ON spans(project_id, gen_ai_operation_name);;
CREATE INDEX idx_spans_project_id_gen_ai_provider_name ON spans(project_id, gen_ai_provider_name);;
CREATE INDEX idx_spans_project_id_gen_ai_request_model ON spans(project_id, gen_ai_request_model);;
CREATE INDEX idx_spans_project_id_gen_ai_response_model ON spans(project_id, gen_ai_response_model);;
CREATE INDEX idx_spans_project_id_service_name ON spans(project_id, service_name);;
CREATE INDEX idx_spans_project_id_session_id ON spans(project_id, session_id);;
CREATE INDEX idx_spans_project_id_start_time_unix_nano ON spans(project_id, start_time_unix_nano);;
CREATE INDEX idx_spans_project_id_trace_id ON spans(project_id, trace_id);;
CREATE INDEX idx_spans_project_id_trace_id_parent_span_id ON spans(project_id, trace_id, parent_span_id);;
